case_study_config <- yaml::yaml.load_file(system.file("conf/case_studies/belimumab.yml", package = "BExTE"))   source_data <- ObservedSourceData$new(case_study_config) summary_measure_likelihood <- case_study_config$summary_measure_likelihood endpoint <- case_study_config$endpoint  target_data <- ObservedTargetData$new(treatment_effect_estimate = case_study_config$target$treatment_effect, treatment_effect_standard_error = case_study_config$target$standard_error, target_sample_size_per_arm = as.integer(case_study_config$target$total / 2), summary_measure_likelihood = case_study_config$summary_measure_likelihood) method_parameters <- list(   initial_prior = "noninformative", # This corresponds to the fact that the posterior for the adults data is derived from an uninformative prior (for consistency with other methods). May be removed in future releases.   heterogeneity_prior = list(family = "inverse_gamma", alpha = 1 / 3, beta = 1) # list(family = "cauchy", location = 0, scale = 10)   # list(family = "half_normal", std_dev = 1) )  method_parameters <- list(   initial_prior = "noninformative", # This corresponds to the fact that the posterior for the adults data is derived from an uninformative prior (for consistency with other methods). May be removed in future releases.   heterogeneity_prior = # list(family = "cauchy", location = 0, scale = 1)     list(family = "half_normal", std_dev = 5) )  env = "full" config_dir <- paste0(system.file(paste0("conf/", env), package = "BExTE"), "/") mcmc_config <- yaml::read_yaml(paste0(config_dir, "/mcmc_config.yml"))  model <- Model$new()  model <- model$create(   case_study_config = case_study_config,   method = "commensurate_power_prior",   method_parameters = method_parameters,   source_data = source_data,   mcmc_config = mcmc_config )  print(model$stan_model_code) ## [1] "
                                      functions {
                                        real g_function(real log_tau) {
                                          return fmax(log_tau, 1); // Define g(τ)
                                        }
                                      }

                                      data {
                                        int<lower=0,upper=2> prior_type; // Type of prior on the commensurability parameter; 0 for inverse_gamma, 1 for half normal, 2 for Cauchy
                                        int<lower=1> NS;       // Number of samples in dataset S
                                        int<lower=1> NT;       // Number of samples in dataset T
                                        real<lower=0> target_sampling_variance;  // Known variance of the target data
                                        real<lower=0> prior_variance; // Prior variance component
                                        real source_treatment_effect_estimate;      // Estimate from dataset S
                                        real target_treatment_effect_estimate;      // Estimate from dataset T
                                        real std_dev; // Parameter for the half normal prior
                                        real location; // Location parameter for the Cauchy prior
                                        real scale; // Scale parameter for the Cauchy prior
                                        real alpha; // Parameter for the inverse_gamma prior
                                        real beta; // Pocation parameter for the inverse_gamma prior
                                      }

                                      parameters {
                                        real<lower=0, upper=1> power_parameter;   // Power parameter
                                        real<lower=0> tau;     // Commensurability parameter
                                        real target_treatment_effect;          // Target treatment effect
                                      }

                                      model {
                                        // Local to the model block: these are
                                        // intermediate quantities, and declaring
                                        // them as transformed parameters would
                                        // write three extra columns per draw to
                                        // the output CSV for no downstream use.
                                        // Stan does not allow constraints on
                                        // local declarations; both quantities are
                                        // non-negative by construction here.
                                        real u = power_parameter * NS + tau * prior_variance;
                                        real tau2 = tau^2;
                                        real log_tau = log(tau);
                                        real marginal_variance = target_sampling_variance / NT
                                                                  + 1 / tau
                                                                  + prior_variance / (power_parameter * NS);

                                        // Priors
                                        if (prior_type == 0) {
                                          tau2 ~ inv_gamma(alpha, beta);
                                          // tau is the parameter and tau2 is a transform of it, so this
                                          // statement needs the log Jacobian of tau -> tau^2, which is
                                          // log(2 * tau). Without it the prior is InvGamma(alpha + 0.5, beta).
                                          target += log(tau);
                                        } else if (prior_type == 1){
                                          // tau is the parameter itself, so Stan's own <lower=0> transform
                                          // already supplies the Jacobian and the truncation normalises it.
                                          tau ~ normal(0, std_dev) T[0, ];
                                        } else if (prior_type == 2){
                                          log_tau ~ cauchy(location, scale);
                                          // Log Jacobian of tau -> log(tau). Without it the prior is improper.
                                          target += -log_tau;
                                        }


                                        power_parameter ~ beta(g_function(log_tau), 1);

                                        // Marginal target-data likelihood for the borrowing
                                        // parameters. Together with the conditional distribution
                                        // below, this gives the joint posterior from equation (9)
                                        // of Hobbs et al. (2011). Omitting this term leaves tau and
                                        // power_parameter distributed according to their priors.
                                        target_treatment_effect_estimate ~ normal(
                                          source_treatment_effect_estimate,
                                          sqrt(marginal_variance));

                                        target_treatment_effect ~ normal(
    (power_parameter * NS * tau * target_sampling_variance * source_treatment_effect_estimate + NT * u * target_treatment_effect_estimate) /
    (power_parameter * NS * tau * target_sampling_variance + NT * u),
    sqrt((u * target_sampling_variance) / (power_parameter * NS * tau * target_sampling_variance + NT * u)));
                                      }
                                      " model$inference(target_data) # Prepare the data for MCMC inference data <- model$prepare_data(target_data) bayesplot::mcmc_hist(model$fit$draws("target_treatment_effect"), binwidth = 0.001) posterior <- model$fit$draws("target_treatment_effect") bayesplot::color_scheme_set("blue") bayesplot::mcmc_dens(posterior, pars = c("target_treatment_effect")) posterior <- model$fit$draws("power_parameter") bayesplot::color_scheme_set("blue") bayesplot::mcmc_dens(posterior, pars = c("power_parameter")) posterior <- model$fit$draws("tau") bayesplot::color_scheme_set("blue") bayesplot::mcmc_dens(posterior, pars = c("tau")) library(posterior) draws_array <- as_draws_array(model$fit) library(bayesplot) mcmc_trace(draws_array, pars = c("tau", "power_parameter", "target_treatment_effect")) mcmc_acf(draws_array, pars = c("tau", "power_parameter", "target_treatment_effect")) mcmc_diagnostics <- model$fit$diagnostic_summary()  n_draws <- mcmc_config$chain_length * mcmc_config$num_chains  # MCMC Effective Sample Size mcmc_ess <- bayesplot::neff_ratio(model$fit) * n_draws  mcmc_ess <- mcmc_ess[["target_treatment_effect"]] print(mcmc_ess) ## [1] 14670.31 bayesplot::neff_ratio(model$fit) ##         power_parameter                     tau target_treatment_effect  ##               0.7412430               0.6586232               0.7335153 rhat_values <- bayesplot::rhat(model$fit) rhat <- rhat_values["target_treatment_effect"] print(rhat) ## target_treatment_effect  ##                1.000068 # number of divergences reported is the sum of the per chain values n_divergences <- sum(mcmc_diagnostics$num_divergent) print(n_divergences) ## [1] 0

